  "stuSess.penaltyChoiceDesc": "Penale: €{penalty}. Importo rimborsabile: €{refundable}.",
  "stuSess.penaltyChoiceDescEarly": "Hai pagato €{refundable} per questa lezione. Scegli un credito sul tuo account per la prossima prenotazione oppure un rimborso.",
