  "stuSess.penaltyChoiceRefund": "Rimborso sul metodo di pagamento",
  "stuSess.penaltyChoiceRefundDesc": "Per un rimborso (€{amount}), contatta info@tutlio.lt. Se hai pagato con carta, un rimborso potrebbe comunque essere avviato automaticamente tramite Stripe.",
  "stuSess.creditAvailable": "Credito disponibile",
  "stuSess.payWithCredit": "Paga con il credito",
  "stuSess.creditAppliedSuccess": "Un credito di €{amount} è stato aggiunto al tuo saldo e verrà applicato automaticamente alla prossima lezione.",
  "stuSess.refundContactNote": "Per un rimborso, contatta <a href=\"mailto:info@tutlio.lt\" class=\"text-amber-800 underline\">info@tutlio.lt</a>.",
  "stuSess.refundSuccessStripeNote": "<p class=\"text-emerald-900 text-sm mb-2\">Domande o problemi? Contatta <a href=\"mailto:info@tutlio.lt\" class=\"underline font-medium\">info@tutlio.lt</a>.</p><p class=\"font-semibold text-emerald-900\">Il tuo rimborso è stato avviato tramite Stripe.</p><p class=\"text-emerald-800 mt-1\">I rimborsi su carta arrivano solitamente entro circa <strong>5–10 giorni lavorativi</strong> (i tempi possono variare in base alla banca). Se non lo ricevi entro i tempi abituali, scrivi a <a href=\"mailto:info@tutlio.lt\" class=\"text-emerald-900 underline font-medium\">info@tutlio.lt</a>.</p>",
  "stuSess.refundSuccessManualTutor": "<p>Questa lezione non sembra essere stata pagata tramite Stripe su Tutlio (ad es. bonifico bancario o contanti). Qui non è previsto un rimborso automatico.</p><p class=\"mt-2\">Per concordare un rimborso, contatta il tuo tutor <strong>{tutor}</strong>: usa l'email o i recapiti presenti nelle prenotazioni oppure forniti direttamente dal tutor.</p>",
  "stuSess.refundSuccessManualOrg": "<p>Questa lezione non sembra essere stata pagata tramite Stripe su Tutlio (ad es. bonifico bancario o contanti). Qui non è previsto un rimborso automatico.</p><p class=\"mt-2\">Poiché segui le lezioni tramite un'organizzazione, contatta <strong>l'amministratore dell'organizzazione</strong> (tramite il tuo tutor o i contatti pubblicati dall'organizzazione).</p>",
  "stuSess.refundTutorFallback": "il tuo tutor",
