  "landing.leadSuccess": "Grazie! Ti contatteremo.",
  "orgTutorPolicy.title": "Regolamento interno per i tutor",
  "orgTutorPolicy.intro": "Leggi il regolamento interno dell'organizzazione prima di utilizzare la piattaforma.",
  "orgTutorPolicy.acceptBtn": "Ho capito",
  "orgTutorPolicy.viewBtn": "Visualizza il regolamento interno",
  "orgTutorPolicy.s1Title": "1. Disposizioni generali",
  "orgTutorPolicy.s1Body": "Questo regolamento disciplina il tuo utilizzo della piattaforma Tutlio (la \"Piattaforma\") come insegnante o tutor (il \"Tutor\"). Sei stato invitato a utilizzare la Piattaforma dall'agenzia educativa, dalla scuola o dal centro di ripetizioni che rappresenti (l'\"Organizzazione\"). La manutenzione e l'assistenza tecnica della Piattaforma sono fornite da MB Tutlio. Utilizzando il tuo account, accetti questo Regolamento e l'Informativa sulla privacy.",
  "orgTutorPolicy.s2Title": "2. Gestione dell'account e degli orari",
  "orgTutorPolicy.s2Intro": "La Piattaforma è progettata per evitarti di dedicare tempo a concordare gli orari delle lezioni con gli studenti.",
  "orgTutorPolicy.s2Link": "Link univoco: ti viene assegnato un link personale per la prenotazione delle lezioni (in base alle materie che insegni), che gli studenti usano per programmare le lezioni.",
  "orgTutorPolicy.s2Calendar": "Sincronizzazione del calendario: la tua disponibilità dipende direttamente dall'integrazione con Google Calendar (sincronizzazione a 2 vie). Sei personalmente responsabile dell'accuratezza e dell'aggiornamento degli orari liberi mostrati nel calendario. La Piattaforma non consente agli studenti di prenotare gli orari contrassegnati come occupati nel calendario.",
  "orgTutorPolicy.s2Security": "Sicurezza dell'account: il tuo account è personale. Devi proteggere le credenziali di accesso e non condividerle con terzi.",
  "orgTutorPolicy.s3Title": "3. Annullamento delle lezioni e lista d'attesa",
  "orgTutorPolicy.s3Intro": "La Piattaforma aiuta a sfruttare al massimo il calendario ed evitare fasce orarie vuote:",
  "orgTutorPolicy.s3Auto": "Se uno studente annulla una lezione, la Piattaforma invia automaticamente una notifica (SMS/email) agli altri studenti nella tua lista d'attesa, offrendo l'orario liberato. Non è richiesta alcuna azione aggiuntiva da parte tua.",
  "orgTutorPolicy.s3Rules": "Le regole di annullamento delle lezioni (con quanto anticipo è possibile annullare e relative conseguenze) sono stabilite dalla tua Organizzazione.",
  "orgTutorPolicy.s4Title": "4. Finanze e pagamenti",
  "orgTutorPolicy.s4Intro": "Non devi occuparti della fatturazione né della riscossione dei pagamenti dai genitori:",
  "orgTutorPolicy.s4Advance": "Tutti i pagamenti degli studenti (o dei genitori) per le tue lezioni vengono riscossi in anticipo tramite la Piattaforma e trasferiti direttamente alla tua Organizzazione.",
  "orgTutorPolicy.s4Confirmed": "Svolgi una lezione solo quando è confermata nel sistema (il che significa che è già stata addebitata).",
  "orgTutorPolicy.s4Contact": "Per il compenso, il calendario dei versamenti e altre questioni finanziarie, contatta direttamente l'amministratore della tua Organizzazione. MB Tutlio non effettua alcuna transazione finanziaria diretta con i Tutor.",
  "orgTutorPolicy.s5Title": "5. Protezione dei dati degli studenti (GDPR)",
  "orgTutorPolicy.s5Intro": "Come Tutor, hai accesso ai dati personali degli studenti, alle note interne e ai materiali didattici. Ti impegni a:",
  "orgTutorPolicy.s5Use": "Utilizzare questi dati esclusivamente per organizzare e svolgere le lezioni.",
  "orgTutorPolicy.s5NoCopy": "Non copiare, esportare o distribuire i contatti degli studenti o dei genitori al di fuori della Piattaforma.",
  "orgTutorPolicy.s5Notes": "Proteggere i dati interni dell'Organizzazione (note sui progressi degli studenti), visibili solo a te e all'amministrazione dell'Organizzazione, non agli studenti o ai genitori.",
  "orgTutorPolicy.s5Termination": "Alla cessazione del rapporto di lavoro con l'Organizzazione, il tuo accesso a questi dati verrà revocato immediatamente.",
  "orgTutorPolicy.s6Title": "6. Funzionamento tecnico e limitazione di responsabilità",
  "orgTutorPolicy.s6Body": "È vietato utilizzare la Piattaforma per scopi illeciti, distribuire link dannosi nei materiali delle lezioni o interferire in altro modo con il sistema. MB Tutlio garantisce il funzionamento e la manutenzione tecnica della Piattaforma, ma non si assume alcuna responsabilità per interruzioni dovute alla tua connessione internet, a guasti dei dispositivi o a impostazioni di Google Calendar configurate in modo errato.",
  "orgTutorPolicy.s7Title": "7. Assistenza e contatti",
  "orgTutorPolicy.s7Org": "Per domande su orari delle lezioni, compensi, assegnazione degli studenti o organizzazione del lavoro, contatta l'amministratore della tua Organizzazione.",
  "orgTutorPolicy.s7Tech": "Per errori tecnici della Piattaforma (sincronizzazione del calendario non funzionante, mancata ricezione delle notifiche), informa l'amministratore della tua Organizzazione, che contatterà il team di assistenza tecnica di Tutlio.",
  "register.orgPolicyConsent": "Utilizzando la nostra piattaforma accetti le",
  "register.orgPolicyLink": "norme interne",
