  "quiz.info.insight.school.eyebrow": "Un aspetto da osservare",
  "quiz.info.insight.solo.title": "Il lavoro amministrativo cresce con ogni studente",
  "quiz.info.insight.solo.body": "Il carico di lavoro raramente arriva come un unico grande problema. Si accumula attraverso piccole azioni ripetute attorno a ogni lezione.",
  "quiz.info.insight.solo.point1": "Spostare una lezione può comportare modifiche al calendario, messaggi e correzioni dei pagamenti.",
  "quiz.info.insight.solo.point2": "Note scollegate rendono più lenta anche la risposta a una semplice domanda di uno studente.",
  "quiz.info.insight.solo.point3": "Un unico flusso di lavoro connesso protegge il tempo per insegnare mentre cresce il numero di studenti.",
  "quiz.info.insight.company.title": "I rallentamenti operativi si moltiplicano in un team di tutor",
  "quiz.info.insight.company.body": "Un piccolo passaggio manuale diventa un ostacolo serio quando ogni tutor, studente e amministratore lo ripete.",
  "quiz.info.insight.company.point1": "Un calendario condiviso offre al team un unico riferimento per le attività quotidiane.",
  "quiz.info.insight.company.point2": "Lo stato della lezione dovrebbe aggiornare compensi dei tutor, fatturazione e report senza reinserire i dati.",
  "quiz.info.insight.company.point3": "Ruoli chiari permettono a ciascuno di agire senza esporre l'intero spazio di lavoro del centro.",
  "quiz.info.insight.school.title": "L'amministrazione scolastica è un'unica catena connessa",
  "quiz.info.insight.school.body": "Contratti, anagrafiche degli studenti, rate, comunicazioni con i genitori e contabilità si influenzano a vicenda. I file separati interrompono questa catena.",
  "quiz.info.insight.school.point1": "Lo stato del contratto dovrebbe essere visibile accanto allo studente, non in un registro separato.",
  "quiz.info.insight.school.point2": "I piani di rateizzazione devono essere chiaramente collegati al pagatore e all'accordo corretti.",
  "quiz.info.insight.school.point3": "I dati finanziari diventano più utili quando sono già strutturati per i report.",
  "quiz.visual.demoTitle": "Guarda lo spazio di lavoro Tutlio in azione",
  "quiz.visual.demoSubtitle.solo": "Una visita dal vivo a calendario, presenze, pagamenti, fatture e pagina pubblica del tutor.",
  "quiz.visual.demoSubtitle.company": "Una visita dal vivo a statistiche del team, carico di lavoro dei tutor, pagamenti, messaggi e accesso dei genitori.",
  "quiz.visual.demoSubtitle.school": "Una visita dal vivo ad anagrafiche centralizzate, pagamenti, comunicazioni e accesso delle famiglie.",
  "quiz.info.story.disclosure": "Flusso di lavoro illustrativo, non una testimonianza di un cliente",
