  "quiz.info.story.solo.title": "Meno amministrazione, più tranquillità prima di ogni lezione",
  "quiz.info.story.solo.body": "Due brevi esempi di come uno spazio di lavoro connesso può cambiare la settimana di un tutor indipendente.",
  "quiz.info.story.solo.disclosure": "Esperienze illustrative di tutor",
  "quiz.info.story.solo.name1": "Rasa",
  "quiz.info.story.solo.role1": "Tutor di matematica",
  "quiz.info.story.solo.story1": "“Quando lezioni, informazioni sugli studenti e pagamenti si trovano in un unico posto, non passo più il venerdì sera a ricostruire la settimana dai messaggi.”",
  "quiz.info.story.solo.name2": "Mantas",
  "quiz.info.story.solo.role2": "Tutor di inglese",
  "quiz.info.story.solo.story2": "“Un calendario chiaro e i promemoria mi permettono di concentrarmi sulla preparazione di ottime lezioni, invece di ripetere sempre le stesse attività amministrative.”",
  "quiz.info.story.company.eyebrow": "Da un cliente Tutlio",
  "quiz.info.story.school.eyebrow": "Da un cliente Tutlio",
  "quiz.info.story.company.title": "Cosa è cambiato per il team PRO KLASĖ",
  "quiz.info.story.company.body": "La loro configurazione riunisce orari, monitoraggio delle lezioni e regole di compenso personalizzate in un unico flusso di lavoro quotidiano.",
  "quiz.info.story.company.disclosure": "Flusso di lavoro del cliente",
