  "quiz.info.story.company.story": "“Prima di Tutlio, modifiche alle lezioni, commenti e ore dei tutor erano sparsi tra i messaggi. Ora tutto il team lavora sullo stesso calendario e non dobbiamo rincorrere gli aggiornamenti a fine mese.”",
