  "quiz.info.story.company.detail": "“La differenza più grande è stata adattare approvazioni, lezioni di recupero e regole di compenso al modo in cui il nostro team lavora già, invece di doverci adeguare a un processo generico.”",
  "quiz.info.story.school.title": "Cosa è cambiato per VšĮ “Laisvi vaikai”",
