  "quiz.info.story.school.customerName": "VšĮ “Laisvi vaikai”",
  "quiz.offer.testimonial.school.name1": "VšĮ “Laisvi vaikai”",
  "quiz.info.story.school.customerType": "Team amministrativo della scuola",
  "quiz.offer.testimonial.school.role1": "Team amministrativo della scuola",
  "quiz.info.story.school.story": "“Volevamo un unico posto dove il team potesse seguire una famiglia dall'iscrizione e dall'accordo fino a ogni rata. Tutlio ci offre questa continuità senza dover mantenere fogli di calcolo paralleli.”",
