  "quiz.info.assurance.company.eyebrow": "Controllo per un team in crescita",
  "quiz.info.assurance.company.title": "Una visione condivisa non deve significare accesso condiviso a tutto",
  "quiz.info.assurance.company.body": "Tutlio è pensato per far lavorare amministratori e tutor nella stessa organizzazione, con accessi adatti al ruolo.",
  "quiz.info.assurance.company.point1": "Separa la supervisione amministrativa dallo spazio di lavoro quotidiano del tutor.",
