  "quiz.info.assurance.school.title": "I dati scolastici richiedono chiarezza, controllo degli accessi e una traccia affidabile",
  "quiz.info.assurance.school.body": "Il flusso scolastico di Tutlio riflette il reale rapporto amministrativo tra personale, studenti, genitori, contratti e pagamenti.",
  "quiz.info.assurance.school.point1": "Mantieni i dati dell'organizzazione in flussi di amministrazione scolastica con accessi basati sui ruoli.",
  "quiz.info.assurance.school.point2": "Monitora gli stati dei contratti e dei pagamenti, senza affidarti alla memoria delle email ricevute.",
  "quiz.info.assurance.school.point3": "Prepara esportazioni strutturate per chi si occupa della contabilità.",
  "quiz.info.assurance.note": "Scegli tu cosa adottare. Tutlio dovrebbe supportare il tuo processo, non imporlo.",
